









create table detalle_producciones (cantidad_requerida numeric(15,4) not null, cantidad_usada numeric(15,4), costo_linea numeric(15,4), precio_por_gramo_snapshot numeric(15,6), suficiente boolean not null, id bigint generated by default as identity, insumo_id bigint not null, produccion_id bigint not null, primary key (id));
create table detalle_recetas (cantidad numeric(15,4) not null, id bigint generated by default as identity, insumo_id bigint not null, receta_id bigint not null, unidad_medida varchar(20) not null check (unidad_medida in ('GRAMO','KILOGRAMO','MILILITRO','LITRO','UNIDAD','CUCHARADA','TAZA')), primary key (id));
create table detalle_ventas (cantidad integer not null, precio_unitario numeric(12,2) not null, subtotal numeric(12,2) not null, id bigint generated by default as identity, producto_id bigint not null, venta_id bigint not null, primary key (id));
create table gastos (monto numeric(12,2) not null, fecha timestamp(6) not null, id bigint generated by default as identity, produccion_id bigint, categoria varchar(30) not null check (categoria in ('MATERIA_PRIMA','SERVICIOS','TRANSPORTE','EQUIPAMIENTO','MANTENIMIENTO','OTROS')), descripcion varchar(150) not null, primary key (id));
create table insumos (activo boolean not null, precio_por_gramo numeric(15,6) not null, stock_actual numeric(15,4) not null, stock_minimo numeric(15,4), id bigint generated by default as identity, version bigint, unidad_medida varchar(20) not null check (unidad_medida in ('GRAMO','KILOGRAMO','MILILITRO','LITRO','UNIDAD','CUCHARADA','TAZA')), categoria varchar(30) not null, marca varchar(30) not null, nombre varchar(60) not null, primary key (id), constraint uk_insumos_nombre unique (nombre));
create table jornadas (activa boolean not null, fecha_apertura timestamp(6) not null, fecha_cierre timestamp(6), id bigint generated by default as identity, abierta_por varchar(60) not null, primary key (id));
create table producciones (cantidad integer not null, costo_total numeric(15,4), fecha timestamp(6) not null, id bigint generated by default as identity, producto_id bigint not null, venta_id bigint, estado varchar(15) not null check (estado in ('PENDIENTE','COMPLETADA')), primary key (id));
create table productos (activo boolean not null, bajo_pedido boolean, precio_venta numeric(12,2) not null, stock_actual integer not null, stock_minimo integer, id bigint generated by default as identity, receta_id bigint, version bigint, nombre varchar(50) not null, primary key (id), constraint uk_productos_nombre unique (nombre));
create table recetas (rendimiento numeric(15,4), id bigint generated by default as identity, insumo_producido_id bigint, nombre varchar(50) not null, descripcion varchar(150), primary key (id), constraint uk_recetas_nombre unique (nombre));
create table usuarios (activo boolean not null, id bigint generated by default as identity, rol varchar(20) not null check (rol in ('ADMIN','VENTAS')), username varchar(50) not null unique, password varchar(255) not null, primary key (id));
create table ventas (total numeric(12,2) not null, fecha timestamp(6) not null, id bigint generated by default as identity, jornada_id bigint, nombre_cliente varchar(100), primary key (id));
create index idx_det_prod_produccion_id on detalle_producciones (produccion_id);
create index idx_det_prod_insumo_id on detalle_producciones (insumo_id);
create index idx_detalle_venta_venta_id on detalle_ventas (venta_id);
create index idx_detalle_venta_producto_id on detalle_ventas (producto_id);
create index idx_gastos_fecha on gastos (fecha);
create index idx_gastos_categoria on gastos (categoria);
create index idx_jornadas_fecha_apertura on jornadas (fecha_apertura);
create index idx_producciones_fecha on producciones (fecha);
create index idx_producciones_venta_id on producciones (venta_id);
create index idx_productos_receta_id on productos (receta_id);
create index idx_ventas_fecha on ventas (fecha);
alter table if exists detalle_producciones add constraint FKe21juvfo347mt0x7kpojmahjx foreign key (insumo_id) references insumos;
alter table if exists detalle_producciones add constraint FKgvl4l9ymossytutlabu9gklqa foreign key (produccion_id) references producciones;
alter table if exists detalle_recetas add constraint FK4b2371lvqb1hp1c6johwplkf foreign key (insumo_id) references insumos;
alter table if exists detalle_recetas add constraint FK8a5lo6afttanny6wfwgn5p1bv foreign key (receta_id) references recetas;
alter table if exists detalle_ventas add constraint FKnunx2ycrr6jfyphwmmifo6lgx foreign key (producto_id) references productos;
alter table if exists detalle_ventas add constraint FK2dn1sdhrbmva44wbs9fy6l7mn foreign key (venta_id) references ventas;
alter table if exists producciones add constraint FK409oeb1px6pb4qj5tlgm0ljxl foreign key (producto_id) references productos;
alter table if exists productos add constraint FKr7qeoj8u4cvq8182njllya5jr foreign key (receta_id) references recetas;
alter table if exists recetas add constraint FKst39lhjlv27fc3g0h62n3x2xk foreign key (insumo_producido_id) references insumos;
